function aiResultCard(type,title,meta,badge,page){return `<div class="ai-result-card"><div class="ai-result-head"><div><div class="ai-result-title">${title}</div><div class="ai-meta">${meta}</div></div><span class="badge b-info">${type}</span></div><div class="toolbar" style="margin-top:9px"><button class="btn btn-light" onclick="aiOpenSource('${page}','${title.replace(/'/g,'')}')">Mở hồ sơ nguồn</button><button class="btn btn-light" onclick="alert('Đã thêm kết quả này vào hồ sơ làm việc / báo cáo nháp.')">Thêm vào báo cáo</button></div></div>`}
function aiRun(){let q=(document.getElementById('aiq')?.value||'').trim();let low=q.toLowerCase();let answer='',results='';
 if(!q){document.getElementById('aiResult').innerHTML='<div class="mini">Hãy nhập câu hỏi hoặc chọn một gợi ý.</div>';return}
 if(low.includes('p-12')||low.includes('máy')||low.includes('thiết bị')){
   answer='<b>Kết luận:</b> Máy P-12 hiện thuộc Đoàn Địa vật lý Mặt đất, đang được Nguyễn Văn Hải nhận sử dụng cho dự án VLDC-2027-001. Hạn kiểm định tiếp theo: 15/03/2027. Không có sự cố mở tại thời điểm demo.';
   results=aiResultCard('Thiết bị','P-12 • Proton Magnetometer','Đang sử dụng • ĐVL Mặt đất • VLDC-2027-001 • Kiểm định 15/03/2027','info','equipment')+aiResultCard('Biên bản','BBBG-TB-2026-118 • Bàn giao thiết bị P-12','07/10/2026 • Người nhận: Nguyễn Văn Hải • DMS/Thiết bị','info','dms');
 } else if(low.includes('nhân sự')||low.includes('cán bộ')||low.includes('gis')||low.includes('chuyên ngành')){
   answer='<b>Kết luận:</b> Hệ thống tìm thấy 3 cán bộ phù hợp tiêu chí địa vật lý + GIS. Theo quyền hiện tại, AI chỉ hiển thị thông tin năng lực phục vụ bố trí công việc, không hiển thị dữ liệu nhân sự nhạy cảm.';
   results=aiResultCard('Nhân sự','Phạm Thu Hà • Chuyên viên kỹ thuật','Địa vật lý • GIS cấp 4/5 • 9 năm kinh nghiệm • Chứng chỉ còn hiệu lực','info','hr')+aiResultCard('Nhân sự','Lê Hoàng Nam • Chủ nhiệm dự án','Địa vật lý • GIS 4/5 • 12 năm • 6 dự án tương tự','info','hr')+aiResultCard('Nhân sự','Nguyễn Đức Hải • Cán bộ hiện trường','Địa vật lý biển • GIS 4/5 • 7 năm','info','hr');
 } else if(low.includes('hợp đồng')||low.includes('công nợ')||low.includes('60 ngày')){
   answer='<b>Kết luận:</b> Có 3 khoản công nợ trên 60 ngày trong dữ liệu demo, tổng 2,1 tỷ đồng. Khoản lớn nhất thuộc HĐ-2026-031 với dư nợ 1,2 tỷ đồng, quá hạn 68 ngày.';
   results=aiResultCard('Hợp đồng','HĐ-2026-031 • Dịch vụ khảo sát địa vật lý','Công nợ 1,2 tỷ • Quá hạn 68 ngày • Đã có dự thảo công văn','danger','contracts')+aiResultCard('Kế toán','AR-031 • Công nợ phải thu','Liên kết HĐ-2026-031 • Đang chờ lãnh đạo duyệt công văn','warn','accounting');
 } else if(low.includes('lịch sử')||low.includes('2019')||low.includes('địa vật lý biển')){
   answer='<b>Kết luận:</b> Tìm thấy 8 hồ sơ lịch sử liên quan địa vật lý biển trong giai đoạn yêu cầu. 5 hồ sơ đã đủ metadata, 2 hồ sơ đang chờ kiểm tra chất lượng scan và 1 dataset có liên kết Geo Data.';
   results=aiResultCard('Legacy','HS-2019-00456 • Khảo sát địa vật lý biển','38 tài liệu • Đã scan • Metadata ✓ • Kho giấy Tủ 07/Ngăn 03','info','dms')+aiResultCard('Geo Data','GEO-2021-MAR-017 • Processed Survey','Dataset 6,8 GB • Có metadata • Quyền: Kỹ thuật/Lãnh đạo','info','projects');
 } else if(low.includes('quyết định')||low.includes('biên bản')||low.includes('tài liệu')||low.includes('nghiệm thu')){
   answer='<b>Kết luận:</b> Hệ thống tìm thấy 6 tài liệu liên quan VLDC-2027-001, gồm quyết định giao nhiệm vụ, kế hoạch, 2 biên bản nghiệm thu, báo cáo tiến độ và hồ sơ điều chỉnh dự toán.';
   results=aiResultCard('Quyết định','QĐ-87/VLĐC • Giao nhiệm vụ VLDC-2027-001','23/03/2026 • Bản chính thức • DMS/Pháp lý','info','dms')+aiResultCard('Biên bản','NT-2026-045 • Biên bản nghiệm thu hạng mục đo điện','07/10/2026 • Đã ký • Khối lượng khóa','ok','projects')+aiResultCard('Báo cáo','BC-TĐ-09/2026 • Báo cáo tiến độ tháng 9','Phiên bản 3 • Đã duyệt • DMS/Báo cáo','info','dms');
 } else if(low.includes('chậm')||low.includes('rủi ro')||low.includes('báo cáo')){
   answer='<b>Tóm tắt điều hành:</b> Có 5 nhiệm vụ nguy cơ chậm; trong đó VLDC-2026-014 có mức cảnh báo cao do tiến độ kỹ thuật 42% trong khi chi phí đạt 81%. Kiến nghị rà lại kế hoạch bù tiến độ, nguồn lực và mốc nghiệm thu.';
   results=aiResultCard('Dự án','VLDC-2026-014 • Cảnh báo Cost vs Progress','Kỹ thuật 42% • Chi phí 81% • Risk: Cao','danger','projects')+aiResultCard('Dự án','VLDC-2027-001 • Theo dõi','Kỹ thuật 62% • Chi phí 68% • Risk: Trung bình','warn','projects');
 } else {
   answer='<b>Kết quả tìm kiếm hợp nhất:</b> Trợ lý đã tìm trên các nguồn bạn đang được phép truy cập và trả về các hồ sơ có độ liên quan cao nhất. Bạn có thể mở hồ sơ gốc để kiểm chứng trước khi sử dụng.';
   results=aiResultCard('DMS','BC-2026-118 • Báo cáo chuyên môn liên quan','Độ phù hợp 91% • DMS/Báo cáo','info','dms')+aiResultCard('Dự án','VLDC-2027-001 • Hồ sơ dự án','Độ phù hợp 86% • Project Center','info','projects');
 }
 document.getElementById('aiResult').innerHTML=`<div class="alert"><span class="dot blue"></span><div><b>Câu hỏi</b><div class="mini">${q.replace(/</g,'&lt;')}</div></div></div><div style="font-size:12px;line-height:1.65;margin-bottom:12px">${answer}</div>${results}<div class="mini" style="margin-top:10px">Nguồn được mô phỏng từ dữ liệu ERP. Khi triển khai thật, mỗi kết quả sẽ kèm quyền truy cập, phiên bản, trích đoạn và liên kết tới hồ sơ gốc.</div>`}
