let taskFilter='all';
function myTasks(){ return taskInbox.filter(t=>t.owner===current || t.cc.includes(current)); }
function ownerTasks(){ return taskInbox.filter(t=>t.owner===current); }
// Badge values are computed in getShellBadges(); this just asks the topbar to re-read them.
function updateTaskBadge(){ shell.refresh(); }

function taskBadge(status){
 if(status.includes('Quá hạn')||status.includes('Bị trả')) return 'b-danger';
 if(status.includes('Chờ')||status.includes('Đang xử lý')) return 'b-warn';
 if(status.includes('Hoàn')||status.includes('Đã duyệt')) return 'b-ok';
 return 'b-info';
}
function taskPriorityBadge(p){ return p==='Cao'?'b-danger':p==='Trung bình'?'b-warn':'b-info'; }
function setTaskFilter(f){ taskFilter=f; render.action(); }
function renderTaskTable(){
 const search=(document.getElementById('taskSearch')?.value||'').toLowerCase();
 const source=document.getElementById('taskSource')?.value||'all';
 const sla=document.getElementById('taskSla')?.value||'all';
 let rows=myTasks().filter(t=>{
   const roleMatch = taskFilter==='all' ? true : taskFilter==='mine' ? t.owner===current : taskFilter==='cc' ? t.owner!==current : taskFilter==='overdue' ? t.overdue : taskFilter==='high' ? t.priority==='Cao' : true;
   const searchMatch=(t.id+' '+t.title+' '+t.type+' '+t.project).toLowerCase().includes(search);
   const sourceMatch=source==='all'||t.source===source;
   const slaMatch=sla==='all'||(sla==='overdue'&&t.overdue)||(sla==='today'&&t.sla.includes('Hôm nay'))||(sla==='soon'&&(t.sla.includes('h')||t.sla.includes('1 ngày')));
   return roleMatch&&searchMatch&&sourceMatch&&slaMatch;
 });
 const body=rows.map(t=>`<tr class="${t.overdue?'task-row-overdue':''} ${t.priority==='Cao'?'task-row-high':''}"><td><b>${t.id}</b><div class="task-source">${t.source} • ${t.project}</div></td><td>${t.title}<div class="mini">Từ: ${t.from} → tiếp theo: ${t.next}</div></td><td><span class="badge ${taskPriorityBadge(t.priority)}">${t.priority}</span></td><td><span class="badge ${taskBadge(t.status)}">${t.status}</span></td><td>${t.owner===current?'<b>Chủ trì</b>':'Theo dõi/CC'}</td><td><span class="badge ${t.overdue?'b-danger':'b-info'}">${t.sla}</span></td><td><div class="task-actions"><button class="btn btn-primary" onclick="taskInboxDetail('${t.id}')">Mở</button><button class="btn btn-light" onclick="openTaskSource('${t.id}')">Phân hệ</button></div></td></tr>`).join('');
 return body||`<tr><td colspan="7" class="mini">Không có tác vụ phù hợp bộ lọc.</td></tr>`;
}
render.action=function(){
 const mine=ownerTasks(); const all=myTasks();
 const overdue=all.filter(t=>t.overdue).length; const high=all.filter(t=>t.priority==='Cao').length; const cc=all.filter(t=>t.owner!==current).length;
 const sources=[...new Set(all.map(t=>t.source))];
 document.getElementById('content').innerHTML=`
 <div class="grid kpis"><div class="kpi"><div class="label">Việc tôi chủ trì</div><div class="value">${mine.length}</div><div class="sub">Cần trực tiếp xử lý</div></div><div class="kpi"><div class="label">Việc liên quan / CC</div><div class="value">${cc}</div><div class="sub">Cần theo dõi hoặc phối hợp</div></div><div class="kpi"><div class="label">Ưu tiên cao</div><div class="value">${high}</div><div class="sub">Trong phạm vi liên quan</div></div><div class="kpi"><div class="label">Quá hạn</div><div class="value">${overdue}</div><div class="sub">Cần xử lý ngay</div></div></div>
 <div class="card" style="margin-top:14px"><div class="card-head"><div><h3>Unified Task Inbox • Hộp việc liên thông</h3><div class="mini">Tập trung việc từ Dự án, Kỹ thuật, KH-TC, Kế toán, TC-HC, Thiết bị, Hợp đồng và Ban Lãnh đạo.</div></div><button class="btn btn-primary" onclick="alert('Demo: tạo tác vụ mới có người chủ trì, người phối hợp, SLA, phân hệ nguồn và điều kiện hoàn thành.')">+ Tạo tác vụ</button></div>
 <div class="inbox-summary"><button class="inbox-chip ${taskFilter==='all'?'active':''}" onclick="setTaskFilter('all')">Tất cả ${all.length}</button><button class="inbox-chip ${taskFilter==='mine'?'active':''}" onclick="setTaskFilter('mine')">Tôi chủ trì ${mine.length}</button><button class="inbox-chip ${taskFilter==='cc'?'active':''}" onclick="setTaskFilter('cc')">Liên quan/CC ${cc}</button><button class="inbox-chip ${taskFilter==='high'?'active':''}" onclick="setTaskFilter('high')">Ưu tiên cao ${high}</button><button class="inbox-chip ${taskFilter==='overdue'?'active':''}" onclick="setTaskFilter('overdue')">Quá hạn ${overdue}</button></div>
 <div class="task-filters"><input id="taskSearch" placeholder="Tìm mã, nội dung, dự án..." oninput="refreshTaskRows()"><select id="taskSource" onchange="refreshTaskRows()"><option value="all">Tất cả nguồn</option>${sources.map(s=>`<option>${s}</option>`).join('')}</select><select id="taskSla" onchange="refreshTaskRows()"><option value="all">Tất cả SLA</option><option value="overdue">Quá hạn</option><option value="today">Hạn hôm nay</option><option value="soon">Sắp hạn</option></select></div>
 <table><thead><tr><th>Mã / Nguồn</th><th>Nội dung</th><th>Ưu tiên</th><th>Trạng thái</th><th>Vai trò của tôi</th><th>SLA</th><th>Thao tác</th></tr></thead><tbody id="taskRows">${renderTaskTable()}</tbody></table></div>
 <div class="grid twoeq" style="margin-top:14px"><div class="card"><h3>Việc chờ tôi bàn giao</h3>${mine.slice(0,3).map(t=>`<div class="alert"><span class="dot ${t.priority==='Cao'?'red':'yellow'}"></span><div><b>${t.id} • ${t.title}</b><div class="mini">Bước tiếp theo: ${t.next} • ${t.sla}</div></div></div>`).join('')||'<div class="mini">Không có.</div>'}</div><div class="card"><h3>Việc tôi cần theo dõi</h3>${all.filter(t=>t.owner!==current).slice(0,3).map(t=>`<div class="alert"><span class="dot blue"></span><div><b>${t.id} • ${t.title}</b><div class="mini">Đang ở ${roles[t.owner]?.title||t.owner} • ${t.status}</div></div></div>`).join('')||'<div class="mini">Không có.</div>'}</div></div>`;
 updateTaskBadge();
};
function refreshTaskRows(){ const el=document.getElementById('taskRows'); if(el)el.innerHTML=renderTaskTable(); }
function openTaskSource(id){ const t=taskInbox.find(x=>x.id===id); if(!t)return; show(t.sourcePage); }
function taskInboxDetail(id){
 const t=taskInbox.find(x=>x.id===id); if(!t)return;
 const roleName=roles[t.owner]?.title||t.owner;
 const isOwner=t.owner===current;
 openModal(`Tác vụ ${id} • ${t.type}`,`<div class="grid twoeq"><div><div class="metric"><span>Nội dung</span><b>${t.title}</b></div><div class="metric"><span>Phân hệ nguồn</span><b>${t.source}</b></div><div class="metric"><span>Dự án/Hồ sơ</span><b>${t.project}</b></div><div class="metric"><span>Người/đơn vị chủ trì</span><b>${roleName}</b></div><div class="metric"><span>Tôi tham gia</span><b>${isOwner?'Chủ trì xử lý':'Phối hợp / Theo dõi'}</b></div><div class="metric"><span>SLA</span><b class="${t.overdue?'danger':'warn'}">${t.sla}</b></div><label>Ý kiến / ghi chú xử lý</label><textarea id="taskNote" rows="4" placeholder="Nhập ý kiến xử lý..."></textarea><div class="task-actions" style="margin-top:10px">${isOwner?`<button class="btn btn-ok" onclick="completeInboxTask('${id}')">Hoàn thành bước</button><button class="btn btn-warn" onclick="returnInboxTask('${id}')">Yêu cầu bổ sung</button><button class="btn btn-primary" onclick="handoffInboxTask('${id}')">Bàn giao → ${t.next}</button>`:`<button class="btn btn-primary" onclick="alert('Đã gửi ý kiến phối hợp cho người chủ trì.');closeModal()">Gửi ý kiến phối hợp</button>`}<button class="btn btn-light" onclick="closeModal();openTaskSource('${id}')">Mở phân hệ nguồn</button></div></div><div><h3>Timeline liên phòng</h3><div class="timeline"><div>07/10 08:20 • Hồ sơ/tác vụ được khởi tạo</div><div>07/10 10:15 • Phòng nghiệp vụ xác nhận phần việc</div><div>07/10 14:40 • Bàn giao sang ${roleName}</div><div><b>Hiện tại • ${t.status}</b></div><div>Bước kế tiếp • ${t.next}</div></div><h3>Người liên quan</h3>${t.cc.map(r=>`<div class="metric"><span>${roles[r]?.title||r}</span><b>Theo dõi / phối hợp</b></div>`).join('')}</div></div>`);
}
function completeInboxTask(id){ const t=taskInbox.find(x=>x.id===id); if(!t)return; t.status='Hoàn thành bước'; t.overdue=false; alert(`Đã hoàn thành bước xử lý của ${id}. Audit được ghi nhận.`); closeModal(); updateTaskBadge(); render.action(); }
function returnInboxTask(id){ const t=taskInbox.find(x=>x.id===id); if(!t)return; t.status='Bị trả bổ sung'; alert(`Đã trả ${id} để bổ sung hồ sơ. Lý do được lưu trong timeline.`); closeModal(); render.action(); }
function handoffInboxTask(id){ const t=taskInbox.find(x=>x.id===id); if(!t)return; t.status='Đã bàn giao'; t.overdue=false; alert(`Đã bàn giao ${id} → ${t.next}. Hệ thống ghi thời điểm, người bàn giao và bắt đầu SLA bước mới.`); closeModal(); updateTaskBadge(); render.action(); }

const _dashboardV61=render.dashboard;
render.dashboard=function(){
 _dashboardV61();
 const all=myTasks(), mine=ownerTasks();
 const target=document.getElementById('content'); if(!target)return;
 target.insertAdjacentHTML('afterbegin',`<div class="card" style="margin-bottom:14px"><div class="card-head"><div><h3>Việc liên quan đến tôi</h3><div class="mini">Tự động tổng hợp từ tất cả phân hệ theo vai trò hiện tại.</div></div><button class="btn btn-primary" onclick="show('action')">Mở Hộp việc (${mine.length})</button></div><div class="grid four"><div class="kpi"><div class="label">Tôi chủ trì</div><div class="value">${mine.length}</div></div><div class="kpi"><div class="label">Phối hợp/CC</div><div class="value">${all.length-mine.length}</div></div><div class="kpi"><div class="label">Ưu tiên cao</div><div class="value">${all.filter(t=>t.priority==='Cao').length}</div></div><div class="kpi"><div class="label">Quá hạn</div><div class="value">${all.filter(t=>t.overdue).length}</div></div></div><table style="margin-top:10px"><tr><th>Mã</th><th>Nội dung</th><th>Nguồn</th><th>SLA</th><th></th></tr>${mine.slice(0,4).map(t=>`<tr><td><b>${t.id}</b></td><td>${t.title}</td><td>${t.source}</td><td><span class="badge ${t.overdue?'b-danger':'b-info'}">${t.sla}</span></td><td><button class="btn btn-light" onclick="taskInboxDetail('${t.id}')">Xử lý</button></td></tr>`).join('')||'<tr><td colspan="5" class="mini">Không có tác vụ cần xử lý trực tiếp.</td></tr>'}</table></div>`);
 updateTaskBadge();
};

