function injectRoleMenusV8(){
 const add=(role,label,items)=>{let arr=roleMenuConfig[role];if(!arr)return;if(!arr.some(g=>g[0]===label))arr.splice(1,0,[label,items]);};
 add('truongdonvi','ĐIỀU HÀNH ĐƠN VỊ',[['directives','➤ Chỉ đạo được giao'],['meetings','◉ Cuộc họp & Kết luận'],['performance','◎ KPI đơn vị'],['risks','⚠ Rủi ro đơn vị']]);
 add('chunhiem','ĐIỀU HÀNH DỰ ÁN',[['directives','➤ Chỉ đạo liên quan'],['meetings','◉ Cuộc họp dự án'],['performance','◎ KPI dự án'],['risks','⚠ Risk dự án']]);
 ['kythuat','kehoach','tochuc','ketoan','ketoantruong'].forEach(r=>add(r,'ĐIỀU HÀNH & HIỆU SUẤT',[['directives','➤ Chỉ đạo liên quan'],['meetings','◉ Cuộc họp & Kết luận'],['performance','◎ KPI phòng/đơn vị'],['risks','⚠ Rủi ro & Tuân thủ']]));
 add('hientruong','ĐIỀU HÀNH CÔNG VIỆC',[['directives','➤ Chỉ đạo liên quan'],['meetings','◉ Lịch họp / kết luận'],['performance','◎ KPI cá nhân']]);
}
