function directiveCard(d){return `<div class="directive-item"><span class="badge ${directiveStatusBadge(d.status)}">${d.status}</span><h5>${d.id} • ${d.title}</h5><div class="directive-meta">${roles[d.owner]?.unit||d.owner} • Hạn ${d.due}<br>Tiến độ ${d.progress}% • Minh chứng ${d.evidence}</div><div class="progress" style="margin:7px 0"><i style="width:${d.progress}%"></i></div><button class="btn btn-light" onclick="directiveDetail('${d.id}')">Chi tiết</button></div>`}

