function unitSpecificMenus(role){
 const common=[['KHÔNG GIAN LÀM VIỆC',[['dashboard','◫ Dashboard'],['action','✓ Hộp việc'],['today','☀ Hôm nay'],['calendar','▦ Lịch'],['plans','▧ Kế hoạch'],['notifications','🔔 Thông báo'],['assistant','✦ Trợ lý AI']]]];
 const by={
  kythuat:[['CHUYÊN MÔN KỸ THUẬT',[['projects','▦ Nhiệm vụ / Dự án'],['research','⚗ KH-CN & Đổi mới'],['dms','▤ Hồ sơ kỹ thuật'],['geodata','⌖ Geo Data'],['reports','▥ Báo cáo kỹ thuật'],['risks','⚠ Risk & Quality']]]],
  kehoach:[['KẾ HOẠCH – TÀI CHÍNH',[['finance','₫ Kế hoạch – Dự toán'],['contracts','⌁ Hợp đồng kinh tế'],['acctassets','⚙ Tài sản theo giá trị'],['receivables','⇢ Công nợ'],['reports','▥ Báo cáo KH-TC']]]],
  tochuc:[['TỔ CHỨC – HÀNH CHÍNH',[['hr','♙ Nhân sự'],['documents','✎ Văn thư – Lưu trữ'],['meetings','▦ Họp & Kết luận'],['equipment','🚗 Cơ sở vật chất / phương tiện'],['digital','◎ Chuyển đổi số'],['reports','▥ Báo cáo TC-HC']]]],
  hangkhong:[['ĐVL HÀNG KHÔNG',[['projects','✈ Nhiệm vụ hàng không'],['equipmentcatalog','⚙ Thiết bị hàng không'],['equipment','↔ Điều phối thiết bị'],['dms','▤ Hồ sơ kỹ thuật'],['geodata','⌖ Dữ liệu bay đo'],['reports','▥ Báo cáo đơn vị']]]],
  matdat:[['ĐVL MẶT ĐẤT',[['projects','⌂ Nhiệm vụ mặt đất'],['equipmentcatalog','⚙ Thiết bị mặt đất'],['equipment','↔ Điều phối thiết bị'],['dms','▤ Hồ sơ kỹ thuật'],['geodata','⌖ Dữ liệu khảo sát'],['reports','▥ Báo cáo đơn vị']]]],
  bien:[['ĐVL BIỂN',[['projects','≈ Nhiệm vụ biển'],['equipmentcatalog','⚙ Thiết bị biển'],['equipment','↔ Điều phối thiết bị'],['dms','▤ Hồ sơ kỹ thuật'],['geodata','⌖ Dữ liệu biển'],['research','⚗ Nghiên cứu biển'],['reports','▥ Báo cáo đơn vị']]]],
  trungtam:[['CÔNG NGHỆ & KIỂM ĐỊNH',[['equipmentcatalog','⚙ Danh mục thiết bị'],['equipment','✓ Kiểm định / Hiệu chuẩn'],['research','⚗ R&D thiết bị'],['projects','▦ Nhiệm vụ được giao'],['dms','▤ Hồ sơ kiểm định'],['reports','▥ Báo cáo Trung tâm']]]]
 };
 return common.concat(by[role]||[]);
}

