 ['DỮ LIỆU & PHÂN TÍCH',[['datahub','◇ Data Hub'],['geodata','⌖ Geo Data'],['archive','▤ Legacy Archive'],['reports','▥ Trung tâm báo cáo'],['digital','◎ Chuyển đổi số'],['audit','↻ Audit Timeline']]]
