const _navigationV10=navigationForRole;
navigationForRole=function(role){
 if(role==='lanhdao') return executiveFullMenu;
 if(['kythuat','kehoach','tochuc','hangkhong','matdat','bien','trungtam'].includes(role)) return unitSpecificMenus(role);
 return _navigationV10(role);
};

