function getResearchPolicy(){return researchRolePolicy[current]||{label:roles[current]?.title||'Cán bộ',can:['Xem danh mục nghiên cứu nội bộ','Đề xuất ý tưởng/sáng kiến','Theo dõi các đề tài được phân quyền'],actions:['idea']};}

// Ensure R&D is visible to everyone as a first-class shared module.
const _navigationAllStaffRnD=navigationForRole;
navigationForRole=function(role){
  const nav=JSON.parse(JSON.stringify(_navigationAllStaffRnD(role)||[]));
  const exists=nav.some(g=>g[1].some(x=>x[0]==='research'));
  if(!exists){
    const shared=nav.find(g=>g[0]==='KHÔNG GIAN LÀM VIỆC');
    if(shared) shared[1].push(['research','⚗ Nghiên cứu KH & Đổi mới']);
    else nav.splice(1,0,['TOÀN LIÊN ĐOÀN',[['research','⚗ Nghiên cứu KH & Đổi mới']]]);
  }
  return nav;
};

function researchActionButtons(policy){
  const a=policy.actions||[]; let out='';
  if(a.includes('idea')) out+=`<button class="btn btn-primary" onclick="researchForm()">+ Đề xuất ý tưởng</button>`;
  if(a.includes('approve')) out+=`<button class="btn btn-ok" onclick="alert('Demo: mở danh sách Gate đang chờ lãnh đạo phê duyệt')">✓ Gate chờ phê duyệt</button>`;
  if(a.includes('review')) out+=`<button class="btn btn-primary" onclick="alert('Demo: mở hàng đợi thẩm định chuyên môn')">Thẩm định chuyên môn</button>`;
  if(a.includes('budget')) out+=`<button class="btn btn-primary" onclick="alert('Demo: mở dự toán KH&CN chờ thẩm định')">Thẩm định kinh phí</button>`;
  if(a.includes('accounting')||a.includes('control')) out+=`<button class="btn btn-primary" onclick="show('accounting')">Mở nghiệp vụ kế toán</button>`;
  if(a.includes('prototype')) out+=`<button class="btn btn-primary" onclick="alert('Demo: mở Prototype / Pilot Board')">Prototype / Pilot</button>`;
  if(a.includes('execute')) out+=`<button class="btn btn-primary" onclick="alert('Demo: chỉ hiện các đề tài mà tài khoản được giao chủ trì/tham gia')">Đề tài của tôi</button>`;
  if(a.includes('staffing')) out+=`<button class="btn btn-light" onclick="show('hr')">Bố trí nhân lực</button>`;
  if(a.includes('council')) out+=`<button class="btn btn-light" onclick="show('calendar')">Lịch hội đồng</button>`;
  if(a.includes('field')) out+=`<button class="btn btn-light" onclick="alert('Demo: mở Electronic Field/Research Notebook')">Nhật ký nghiên cứu</button>`;
  if(!out) out=`<button class="btn btn-primary" onclick="researchForm()">+ Đề xuất ý tưởng</button>`;
  return out;
}

